package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamKandyTradBank1 {
    private const val T = "මහනුවර යුගයේ සිතුවම්, දේශීය ශෛලිය හා වාස්තු කැටයම්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("මහනුවර යුගයේ චිත්‍ර කලා සම්ප්‍රදායේ උච්චතම හා විශිෂ්ටතම උදාහරණය ලෙස සැලකෙන විහාරය කුමක්ද?", "දෙගල්දොරුව රජමහා විහාරය", "සීගිරිය බිතුසිතුවම් ලෙන", "තිවංක පිළිමගෙය", "ගෝනගොල්ල විහාරය", "කීර්ති ශ්‍රී රාජසිංහ හා රාජාධිරාජසිංහ රජ සමයේ නිර්මාණය වූ දෙගල්දොරුව උඩරට සම්ප්‍රදායේ අග්‍රගණ්‍ය සිතුවම් වේ."),
        q("දෙගල්දොරුව රජමහා විහාරයේ බිතුසිතුවම් ඇඳීමට ප්‍රධානත්වය දුන් සුප්‍රකට භික්ෂු සිත්තරා කවුද?", "දේවරගම්පල සිල්වත් තැන", "වැලිවිට සරණංකර හිමියන්", "තොටගමුවේ ශ්‍රී රාහුල හිමියන්", "මිගෙට්ටුවත්තේ ගුණානන්ද හිමියන්", "නීලගම පටබැඳි හා දෙවරගම්පල සිල්වත්තැන ඇතුළු ශිල්පීන් දෙගල්දොරුවේ සිතුවම් නිර්මාණය කළහ."),
        q("දෙගල්දොරුව විහාරයේ ප්‍රධාන බිතුසිතුවම් අතර විශිෂ්ට ලෙස සිතුවම් කර ඇති ජාතක කතා හතර මොනවාද?", "වෙස්සන්තර, සුතසෝම, මහා සීලව හා සත්තුභත්ත ජාතක කතා", "මහෞෂධ හා නළ දමයන්ති පමණි", "සස හා අසංඛවතී ජාතක පමණි", "රාමායණය හා කුවේණි පුවත", "වෙස්සන්තර ජාතකය ඇතුළු ජාතක කතා සතර හා මාර පරාජය දෙගල්දොරුවේ විශිෂ්ට ලෙස සිතුවම් කර ඇත."),
        q("මහනුවර යුගයේ චිත්‍ර කලාව නැවත පුනර්ජීවනය කිරීමට අනුග්‍රහය දැක්වූ ප්‍රධාන මහනුවර රජතුමා කවුද?", "කීර්ති ශ්‍රී රාජසිංහ රජතුමා", "පළමුවන විමලධර්මසූරිය රජු", "පළමුවන කාශ්‍යප රජු", "මහා පරාක්‍රමබාහු රජු", "18 වන සියවසේ කීර්ති ශ්‍රී රාජසිංහ රජු වැලිවිට සරණංකර හිමිගේ උපදෙස් පරිදි විහාර කර්මාන්ත ප්‍රකෘතිමත් කළේය."),
        q("මහනුවර යුගයේ බිතුසිතුවම්වල ප්‍රධාන වශයෙන් භාවිත කර ඇති පසුබිම් වර්ණය කුමක්ද?", "රතු (ගුරුගල් හා සාදිලිංගම්)", "දීප්තිමත් අහස් නිල් පැහැය", "කළු අඟුරු පසුබිම", "ලා කොළ පසුබිම", "උඩරට සම්ප්‍රදායේ බොහෝ සිතුවම්වල ප්‍රධාන පසුබිම රතු වර්ණයෙන් පුරවා ඒ මත කහ හා සුදු රූප අඳියි."),
        q("මහනුවර යුගයේ සිතුවම්වල කතා පුවතක් නිරූපණය කර ඇති ආකෘතිමය ක්‍රමය හඳුන්වන්නේ කුමන නමකින්ද?", "අඛණ්ඩ ආඛ්‍යාන තීරු ක්‍රමය (Continuous Narrative Strips)", "ත්‍රිමාණ ඡායාරූප ක්‍රමය", "වියුක්ත කොටු චිත්‍ර ක්‍රමය", "එකම රූපයක් තනි කැන්වසයක ඇඳීම", "වමේ සිට දකුණට හෝ දකුණේ සිට වමට දිවෙන සමාන්තර තිරස් තීරු තුළ කතා පෙළට ඇඳ ඇත."),
        q("මහනුවර යුගයේ චිත්‍ර කලාවේ මානව රූප ඇඳීමේදී අනුගමනය කළ ස්වරූපය කුමක්ද?", "පැතලි ද්විමාන රූප හා පැතිකඩ (Profile) මුහුණු ලක්ෂණය", "සම්පූර්ණ ත්‍රිමාණ සෙවණැලි සහිත රූප", "පිටුපස හැරුණු කූරු රූප", "පුනරුද යුගයේ කායව්‍යවච්ඡේද රූප", "සෙවණැලි රහිතව ද්විමාන තලයේ පැහැදිලි බාහිර රේඛාවකින් හා පැතිකඩ ඉරියව්වෙන් රූප ඇඳීම විශේෂයකි."),
        q("මහනුවර සිතුවම්වල සිරුර පැත්තට හෝ පැතිකඩින් ඇන්දද, දෑස හා උරහිස් ඉදිරියට පෙනෙන සේ ඇඳීම සිදු කරන්නේ ඇයි?", "චරිතයේ අනන්‍යතාව හා ප්‍රකාශනය වඩාත් පැහැදිලිව දැක්වීමට", "ශිල්පියාට පැතිකඩ ඇස් ඇඳීමට නොදැන සිටීම නිසා", "කඩදාසි මදි වීම නිසා", "වර්ණ ඉතිරි කිරීම සඳහා", "පුරාණ මිසර චිත්‍ර මෙන් පැතිකඩ මුහුණේ සම්පූර්ණ ඇස ඇඳීම මහනුවර සම්ප්‍රදායේ ලක්ෂණයකි."),
        q("දෙගල්දොරුව විහාරයේ ඇති ඉතා ප්‍රකට 'මාර පරාජය' සිතුවමේ නිරූපණය කර ඇති මාර සේනාවේ සුවිශේෂීත්වය කුමක්ද?", "සත්ව හිස් සහිත යක්ෂයන් හා තුවක්කු වැනි ආයුධ දරා සිටීම", "සියල්ලන්ම භාවනා කරන භික්ෂූන් වීම", "යුරෝපීය කාන්තාවන් පමණක් සිටීම", "මාරයා නොමැතිව ගස් පමණක් තිබීම", "යුගයේ සමාජ වටපිටාවට අනුව තුවක්කු, කඩු හා බියකරු සත්ව මුහුණු සහිත මාර සේනාව ඇඳ ඇත."),
        q("ලෝක උරුම 'දඹුල්ල රජමහා විහාරයේ' (රංගිරි දඹුලු ලෙන්) ලෙන් සිතුවම්වලින් බහුතරයක් අදටත් දැකිය හැක්කේ කුමන යුගයේ ශෛලියෙන්ද?", "මහනුවර යුගයේ (18 වන සියවසේ) සිතුවම් ශෛලිය", "සීගිරි ත්‍රිමාණ ශෛලිය", "ග්‍රීක රෝම ශෛලිය", "20 වන සියවසේ කැන්වස් ශෛලිය", "කීර්ති ශ්‍රී රාජසිංහ රජ සමයේ නීලගම පටබැඳි ශිල්පී පරපුර විසින් දඹුලු ලෙන් වහලය සිතුවමින් සරසා ඇත."),
        q("දඹුල්ල රජමහා විහාරයේ ලෙන් සිවිලිමේ සිතුවම් ඇඳීමේදී කලාකරුවා දැක්වූ අතිවිශේෂ තාක්ෂණික දක්ෂතාව කුමක්ද?", "අසම වහලයේ අඛණ්ඩ රටා ගැළපීම", "ලෙන් වහලය කොන්ක්‍රීට් කිරීම", "සිවිලිම හැර බිම පමණක් ඇඳීම", "වීදුරු කැඩපත් ඇලවීම", "වර්ග අඩි විසිදහසකට අධික වක්‍ර ගල් වහලය පුරා මල් රටා හා සූවිසි විවරණ මනාව සිතුවම් කර ඇත."),
        q("මහනුවර යුගයේ බිතුසිතුවම්වල දක්නට ලැබෙන 'කළු බාහිර රේඛාව' (Outline) යෙදීමේ අරමුණ කුමක්ද?", "රතු පසුබිමෙන් කහ හා සුදු රූප පැහැදිලිව වෙන් කර දැක්වීම", "සිතුවම කළු කර සැඟවීම", "වර්ණ වැරදීම් වැසීම පමණක්", "කාර්මික බෝඩරයක් සෑදීම", "පැතලි වර්ණ යෙදූ පසු තියුණු කළු රේඛාවකින් මායිම් දැක්වීම රූපවලට ප්‍රබල ස්වරූපයක් දෙයි."),
        q("මහනුවර යුගයේ සිතුවම් ශිල්පීන් කහ පැහැය නිපදවා ගැනීමට යොදා ගත් දේශීය ශාක ද්‍රව්‍යය කුමක්ද?", "ගොකටු කිරි (Gamboge)", "නිල් අවරිය", "කළු දැලි", "සාදිලිංගම්", "ගොකටු ගසේ පොත්තෙන් ගන්නා ලාටු හෙවත් කිරි ජලයේ දිය කර ඉතා දීප්තිමත් කහ වර්ණය සාදා ගත්හ."),
        q("මහනුවර යුගයේ සිතුවම් ශිල්පීන් ස්වභාවික ඛනිජ හා ශාක වර්ණ ආරක්ෂා කිරීම සඳහා අවසානයේ ආලේප කළ ද්‍රව්‍යය කුමක්ද?", "දොරණ තෙල් හා දුම්මල වාර්නිෂ්", "කෘත්‍රිම පෙට්‍රල් සහ තිනර්", "විනාකිරි සහ ලුණු දියර", "සිමෙන්ති කිරි තට්ටුව", "දොරණ තෙල් හා හල් දුම්මල උණු කර සෑදූ වලිත්ති ආලේපය සිතුවම්වලට දිලිසීම හා ආරක්ෂාව දුන්නේය."),
        q("මහනුවර යුගයේ 'විහාර බිතුසිතුවම්වල' කතා පුවත් අතර හිස් ඉඩ පිරවීමට බහුලව ඇඳ ඇති සාම්ප්‍රදායික මල කුමක්ද?", "නෙළුම් මල සහ සීන මල / කතුරුමුරුංගා වැනි පිපුණු මල්", "රෝස හා ටියුලිප් මල්", "කැක්ටස් පතොක් මල්", "නූතන වියුක්ත රේඛා", "සෑම රූප දෙකක් අතර හිස් අවකාශයේ අලංකාර කුඩා මල් පොහොට්ටු හා රවුම් මල් ඇඳ පිරවීම (Horror Vacui) සිරිතකි."),
        q("මහනුවර චිත්‍ර සම්ප්‍රදායේ 'වෘක්ෂ හා ගස්වැල්' නිරූපණය කර ඇති ආකාරය කෙබඳුද?", "සමමිතික හා සැරසිලිමය හැඩයෙන් කොළ පොකුරු මෙන් ඇඳීම", "වනාන්තරයේ සැබෑ අතුපතර ලෙස ත්‍රිමාණව ඇඳීම", "ගස් කිසිවක් නොඇඳීම", "වියළි දර කෝටු ලෙස පමණක් ඇඳීම", "එකම වර්ගයේ ගසක කොළ රටා වෘත්තාකාර පොකුරක් සේ ශෛලිගතව ඇඳීම මෙහි ලක්ෂණයකි."),
        q("මහනුවර යුගයේ සිතුවම්වල 'සමූහගත මිනිසුන්ගේ උස' තීරණය වන්නේ කුමක් මතද?", "චරිතයේ ආගමික හා සමාජීය වැදගත්කම මත (Hieratic Scaling)", "වයස අනුව මීටරයෙන් මැනීමෙන්", "දුර හා ළඟ දෘෂ්ටිකෝණ නියමයෙන්", "සියල්ලන් එකම සෙන්ටිමීටර ප්‍රමාණයෙන්", "බුදුන් වහන්සේ හා රජු විශාලවද සාමාන්‍ය සේවකයින් කුඩාවටද ඇඳීම වැදගත්කම පෙන්වයි."),
        q("මහනුවර යුගයේ සිතුවම්වල ඇඳ ඇති 'නිලමේවරුන්ගේ හා රජවරුන්ගේ' ඇඳුම් පැළඳුම් මගින් පෙනෙන්නේ කුමක්ද?", "18 වන සියවසේ සමකාලීන උඩරට සමාජ ඇඳුම් හා සංස්කෘතිය", "ක්‍රි.පූ. ඉන්දීය ඇඳුම් පමණක්", "නූතන බටහිර ටයි කෝට් ඇඳුම්", "මිසර ලිනන් රෙදි ඇඳුම්", "ජාතක කතාවල එන ඉන්දීය රජවරුන් පවා මහනුවර රජුන් හා නිලමේවරුන් මෙන් උඩරට මුල් ඇඳුමින් ඇඳ ඇත."),
        q("මහනුවර යුගයේ ප්‍රසිද්ධ 'මැදවල ටැම්පිට විහාරයේ' බිතුසිතුවම්වල විශේෂත්වය කුමක්ද?", "ගල් කණු මත කුඩා විහාර කුටිය", "විශාල ගල් ලෙනක් වීම", "සිතුවම් සියල්ල නිල් පැහැ වීම", "තෙල් සායම් භාවිතය", "හාරිස්පත්තුවේ මැදවල ටැම්පිට විහාරය කීර්ති ශ්‍රී රාජසිංහ රජ සමයේ අගනා සිතුවම් සහිත විහාරයකි."),
        q("කුරුණෑගල දිස්ත්‍රික්කයේ පිහිටි 'රිදී විහාරයේ' ඇති මහනුවර යුගයේ සිතුවම් හා සැරසිලිවල විශේෂ අංගයක් කුමක්ද?", "බිතුසිතුවම්, ඇත්දත් හා පිඟන් කැටයම්", "ප්‍රාග් ඓතිහාසික කෙටුම් පමණක්", "පෘතුගීසි කාලතුවක්කු සිතුවම්", "වීදුරු මොසැයික් බිත්ති", "රිදී විහාරයේ මහනුවර සිතුවම් සමඟ ක්‍රිස්තු කතා පිඟන් කැටයම් හා ඇත්දත් පංචනාරි ඝටය දක්නට ඇත."),
        q("මහනුවර දළදා මාලිගාවේ 'හේවිසි මණ්ඩපයේ' හා 'උඩු මාලයේ' ඇති සිතුවම්වල ප්‍රධාන තේමා කවරේද?", "සූවිසි විවරණය හා දළදා වංශය", "බටහිර යුද ජයග්‍රහණ", "සත්ව දඩයම් කතා", "නූතන කර්මාන්තශාලා", "දළදා මාලිගාවේ බිත්ති හා වහලය උඩරට සම්ප්‍රදායේ උසස් මෝස්තර හා බෞද්ධ සිතුවමින් සරසා ඇත."),
        q("සූරියගොඩ විහාරය සහ ලංකාතිලක විහාරයේ ඇති මහනුවර යුගයේ සිතුවම්වල පොදු ගුණාංගය කුමක්ද?", "පැහැදිලි රතු පසුබිම, තීරු බෙදීම සහ සරල ජන සිත්තර ආර", "ත්‍රිමාණ සෙවණැලි සහිත පුනරුද ශෛලිය", "තනි කළු-සුදු රේඛා සටහන්", "ජපන් තීන්ත චිත්‍ර ශෛලිය", "මහනුවර කලාපයේ ප්‍රධාන විහාර රැසක මෙම උඩරට සම්භාව්‍ය ජන චිත්‍ර ආර දක්නට ලැබේ."),
        q("මහනුවර යුගයේ චිත්‍ර කලාවේ 'දකුණු පළාතේ' (උදා: තෙල්වත්ත, මුල්කිරිගල, කතළුව) විහාර සිතුවම්වල හඳුනාගත හැකි ප්‍රාදේශීය වෙනස කුමක්ද?", "පහතරට කලා ආරේදී සමහර බටහිර වස්තූන්, වර්ණ විවිධත්වය හා වක්‍ර රේඛා මඳක් නිදහස් වීම", "තෙල්වත්තේ කිසිදු බුදු රුවක් නොඇඳීම", "පහතරට සිතුවම් කළුගලින් කැටයම් කිරීම", "මහනුවර තේමා සම්පූර්ණයෙන් අත්හැරීම", "19 වන සියවස දෙසට යන විට පහතරට සිතුවම්වල ලන්දේසි-බ්‍රිතාන්‍ය සමාජ අංග හා නව වර්ණ එක්විය."),
        q("තෙල්වත්ත තොටගමුව රජමහා විහාරයේ හා කතළුව පූර්වාරාමයේ සිතුවම් අයත් වන්නේ කුමන ශෛලිමය ශාඛාවටද?", "දකුණු හෙවත් පහතරට ශෛලියට", "අනුරාධපුර සීගිරි ශෛලියට", "ඉතාලි බැරොක් ශෛලියට", "චීන මිං ශෛලියට", "උඩරට මූලික රීතිය මත පදනම්ව දකුණු මුහුදුබඩ ආභාසය එක් වූ පහතරට සිතුවම් ශාඛාව මෙයයි."),
        q("මහනුවර යුගයේ සිතුවම්වල 'බිත්ති බදාමය' සකස් කිරීම සඳහා භාවිත කළ ප්‍රධාන ද්‍රව්‍ය මොනවාද?", "රතු මැටි, කුඹුක් හෝ මකුළු මැටි, වැලි, දහයියා සහ හුණු", "පෝට්ලන්ඩ් සිමෙන්ති සහ යකඩ කුඩු", "ප්ලාස්ටර් ඔෆ් පැරිස් සහ ග්ලූ", "රබර් කිරි සහ පෙට්‍රල්", "මැටි තට්ටුව මත පිරිසිදු මකුළු මැටි හා හුණු ස්තරයක් ගා සිතුවම් ඇඳීමට සකසා ගත්හ."),
        q("මහනුවර සිත්තරා සුදු වර්ණය සාදා ගැනීමට භාවිත කළ ප්‍රධාන දේශීය ද්‍රව්‍යය කුමක්ද?", "මකුළු මැටි හෙවත් කිරිමැටි (Kaolin)", "ටයිටේනියම් ඩයොක්සයිඩ් කුඩු", "සුදු ප්ලාස්ටික් තීන්ත", "සීනි සහ පිටි", "කඳුකරයේ හමුවන සුදු මකුළු මැටි ඉතා සියුම්ව පෙරා සුදු පැහැය ලබා ගැනීමට භාවිත කළහ."),
        q("මහනුවර යුගයේ සිතුවම්වල 'සාදිලිංගම්' හෙවත් රතු පැහැයට අමතරව භාවිත කළ අඳුරු දුඹුරු හෝ කළු පැහැය නිපදවූයේ කුමකින්ද?", "තෙල් පහන් දැලි හා අඟුරු කුඩු", "තාර සහ කෘත්‍රිම ඩයි", "රසදිය සහ තඹ කුඩු", "මයිකා සහ රතු මැටි", "හොඳින් පිළිස්සූ කැකුණ තෙල් දැලි හා අඟුරු දිවුල් ලාටු සමඟ අඹරා කළු තීන්ත සෑදූහ."),
        q("මහනුවර යුගයේ සිත්තරුන් පින්සල් (තෙලිකූරු) සාදා ගැනීම සඳහා යොදා ගත් අමුද්‍රව්‍ය මොනවාද?", "ලේන ලොම්, එළු ලොම් හෝ වැටකෙයියා මුල් කෙඳි", "ප්ලාස්ටික් හා නයිලෝන් කෙඳි", "ලෝහ කම්බි කැබලි", "කපු පුළුන් කැබලි පමණක්", "සියුම් රේඛා ඇඳීමට සත්ව ලොම්ද පසුබිම පිරවීමට තැළූ වැටකෙයියා මුල් කෙඳිද භාවිත කළහ."),
        q("මහනුවර යුගයේ සිතුවම්වල කතා අතර හමුවන 'නරකාදියේ දර්ශන' (උදා: දෙගල්දොරුව, දඹුල්ල, මුල්කිරිගල) ඇඳීමේ අරමුණ කුමක්ද?", "පව් කිරීමේ විපාක පෙන්වා ජනතාව යහමගට යොමු කිරීම", "යක්ෂයන්ට වන්දනා කිරීමට සැලැස්වීම", "චිත්‍ර ශිල්පියාගේ කෝපය පිට කිරීම", "විනෝද හාස්‍යජනක කාටූන් පෙන්වීම", "සාමාන්‍ය ජනතාවට සීලය හා පින් පව් ගැන පහසුවෙන් අවබෝධ කරවීම දෘශ්‍ය ධර්ම දේශනාවක් විය."),
        q("මහනුවර සිතුවම්වල 'අඛණ්ඩ ආඛ්‍යාන ක්‍රමයේදී' එකම ප්‍රධාන චරිතය එකම සිතුවම් තීරුවේ කිහිප වරක් ඇඳීමෙන් පෙන්වන්නේ කුමක්ද?", "කාලය ගලා යාම හා කතාවේ ඊළඟ සිදුවීමට මාරු වීම", "එකම පුද්ගලයාට නිවුන් සහෝදරයන් සිටින බව", "ශිල්පියාට වැරදී නැවත ඇඳි බව", "කණ්ණාඩියකින් පෙනෙන ප්‍රතිබිම්බය", "වෙස්සන්තර රජු ඇතු දන් දීම, රථය දන් දීම ආදී අවස්ථා පෙළට ඇඳ කාලයේ ගලායාම පෙන්වයි."),
        q("මහනුවර සම්ප්‍රදායේ 'නායක හා පරිවාර රූප' අඳින විට පසුබිමේ ගස් හෝ පූජා භාණ්ඩ වෙනස් කිරීමෙන් සිදු කරන්නේ කුමක්ද?", "එක් දර්ශනයකින් තවත් දර්ශනයකට මාරු වන සීමාව හැඟවීම", "වර්ණ කළමනාකරණය කිරීම පමණක්", "බිත්තියේ දිග මැනීම", "කෘමීන් විනාශ කිරීම", "ගසක් හෝ ගොඩනැගිලි කුළුණක් යොදා ජාතක කතාවේ අවස්ථා එකිනෙකින් වෙන් කර දක්වයි."),
        q("මහනුවර යුගයේ චිත්‍ර කලාවේ 'මුහුණේ හැඟීම් ප්‍රකාශනය' (Expression) සිදුවන්නේ කුමන ආකාරයටද?", "දෑත් හා ශරීර ඉරියව්වෙන් පෙන්වීම", "නළල රැලි ගන්වා හැඬීම පෙන්වීම", "රූප සියල්ලටම විශාල සිනහවක් ඇඳීම", "විකට වෙස්මුහුණු පැළඳීම", "මහනුවර රූපවල මුහුණු බොහෝ විට ශාන්ත සමාන බවක් ගන්නා අතර අත් ඉරියව්වලින් කතාව කියයි."),
        q("මහනුවර යුගයේ බිතුසිතුවම්වල 'සත්ව රූප' (ඇතා, අශ්වයා, මුවා, සිංහයා) ඇඳීමේදී දක්නට ලැබෙන විශේෂ ලක්ෂණය කුමක්ද?", "ශෛලිගත රටාවකට අනුව සජීවී හා අලංකාර හැඩයකින් යුක්ත වීම", "ඡායාරූප යථාර්ථවාදයෙන් යුක්ත වීම", "සම්පූර්ණ කළු තිත්වලින් පමණක් තැනීම", "ජ්‍යාමිතික කෝණයෙන් කොටු කර ඇඳීම", "ජන කලා ආභාසය අනුව ඇතුන්, අශ්වයන් හා මුවන් ඉතා සුන්දර ශෛලිගත හැඩයකින් ඇඳ ඇත."),
        q("දඹුල්ල රජමහා විහාරයේ 'මහාරාජ ලෙනෙහි' (ලෙන් අංක 2) වහලයේ සිතුවම් කර ඇති ප්‍රධාන ඓතිහාසික හා ආගමික දර්ශන මොනවාද?", "දුටුගැමුණු-එළාර යුද්ධය, මහින්දාගමනය, සත්සතිය හා මාර පරාජය", "පළමු ලෝක යුද්ධය හා රුසියානු විප්ලවය", "සීගිරි ලලනාවන් පන්සියය", "ග්‍රීක ඔලිම්පික් තරග", "බුදු සිරිත සමඟ ලක්දිව ශාසන ඉතිහාසයේ වැදගත් අවස්ථාද මහාරාජ ලෙනෙහි සිතුවම් කර ඇත."),
        q("මහනුවර යුගයේ 'විහාර බිතුසිතුවම්වල' සිවිලිම (Ceiling) අලංකරණය සඳහා බහුලව යොදාගෙන ඇති මෝස්තරය කුමක්ද?", "වියන් රෙදි රටා, නෙළුම් මල් පදක්කම් හා ලියවැල්", "නගර සිතියම් සහ මහා මාර්ග", "සතුන් දඩයම් කරන කූරු රූප", "හිස් සුදු බදාමය පමණක්", "කිරි සුදු වියන් රෙදිවල මෙන් මල් හා පලාපෙති රටා සිවිලිම පුරා අඛණ්ඩව ඇඳ ඇත."),
        q("මහනුවර යුගයේ චිත්‍ර ශිල්පියා පිළිබඳව සඳහන් 'නීලගම' හා 'දේවරගම්පල' වැනි නම් මගින් හෙළි වන්නේ කුමක්ද?", "කලාව පරම්පරාගත ශිල්පීය පවුල් හා භික්ෂු ගුරුකුල මගින් පවත්වාගෙන ගිය බව", "චිත්‍ර ඇඳීම විදේශීය කම්හල්වල කළ බව", "චිත්‍ර ශිල්පීන් රහසිගතව සැඟවී සිටි බව", "සියලු චිත්‍ර එකම පුද්ගලයෙකු විසින් ඇඳි බව", "රාජකීය ගම්වර ලැබූ සිත්තර පරම්පරා කිහිපයක්ම උඩරට විහාර කර්මාන්ත සිදු කළහ."),
        q("මහනුවර යුගයේ සිතුවම්වල 'රාජකීය හා දිව්‍යමය' ඇඳුම්වල ඇති පොදු ලක්ෂණය කුමක්ද?", "සියුම් ඉරි රටා, රැලි තැබූ තුප්පොට්ටි හා මුතු පබළු මෝස්තර", "රළු සම් හා කොළ අතු ඇඳුම්", "කිසිදු රටාවක් නැති තනි කළු ඇඳුම්", "නූතන ජින්ස් හා ටී-ෂර්ට්", "ඇඳුම් මත සියුම් තිත් හා රේඛා රටා යෙදීමෙන් සිත්තරා මනා අලංකරණ හැකියාවක් පෙන්වා ඇත."),
        q("මහනුවර යුගයේ 'වෙස්සන්තර ජාතකය' දෙගල්දොරුවේ සිතුවම් කර ඇති ආකාරයේ කැපී පෙනෙන සිදුවීමක් කුමක්ද?", "ජූජක බමුණා ජාලිය-කෘෂ්ණජිනා දරුවන් බැඳ කෝටුවකින් තළමින් රැගෙන යන දර්ශනය", "වෙස්සන්තර රජු විශ්වවිද්‍යාලයක ඉගැන්වීම", "දරුවන් නැවක නැගී විදේශගත වීම", "සිංහයෙකු මාලිගාව කඩා දැමීම", "දෙගල්දොරුවේ සිත්තරා ජූජක බමුණාගේ කෲර බව හා දරුවන්ගේ දුක ඉතා සංවේදීව දක්වා ඇත."),
        q("මහනුවර යුගයේ සිතුවම්වල 'විදේශීය ආභාසය' කිසියම් දුරකට පෙනෙන තැනක් වන්නේ කුමන ස්ථානයකද?", "දකුණු ඉන්දීය මදුරා ආභාසය", "චීන සේද මාවතේ කලා ආභාසය", "මිසර හයිරොග්ලිෆික්ස් ආභාසය", "ඇමරිකානු පොප් කලා ආභාසය", "නායක්කර් සබඳතා නිසා දකුණු ඉන්දීය තන්ජෝර් හා ලේපාක්ෂි සිතුවම් ලක්ෂණ උඩරට කලාවට මුසු විය."),
        q("මහනුවර යුගයේ 'පොත් කවර' (කම්බ) හා 'පුස්කොළ පොත්' සිතුවම් කලාවට සම්බන්ධ වන්නේ කෙසේද?", "විහාර බිතුසිතුවම් ශෛලියෙන්ම ලී පොත් කම්බාවල ලියවැල් හා රූප පින්තාරු කිරීම", "පොත් කවර මත ප්ලාස්ටික් කවර දැමීම", "කම්පියුටර් මුද්‍රණ කවර සෑදීම", "පොත් කවරවල තෙල් සායම් භූ දර්ශන ඇඳීම", "උඩරට විහාර බිතුසිතුවම් හා ලාක්ෂා කලා මෝස්තර පුස්කොළ පොත් කම්බාවලද යොදා ගැනිණි."),
        q("මහනුවර යුගයේ චිත්‍ර ශිල්පීන් 'පාවිච්චි කළ දේශීය වර්ණ' අතර 'නිල්' පැහැය ලබා ගත්තේ කුමකින්ද?", "නිල් අවරිය හෝ ඛනිජ නිල්", "සාදිලිංගම් සහ හිරියල්", "පොල් කටු අඟුරු", "කිරි මකුළු මැටි", "ශාකමය නිල් අවරිය (Indigo) සහ පසුකාලීනව ආනයනික නිල් කුඩු කලාතුරකින් භාවිත කළහ."),
        q("මහනුවර යුගයේ බිතුසිතුවම්වල 'සත්සතිය' හා 'සූවිසි විවරණය' නිතර සිතුවම් කිරීමෙන් පිළිබිඹු වන්නේ කුමක්ද?", "සම්බුද්ධ චරිතය කෙරෙහි ඇති ශ්‍රද්ධාව", "රජවරුන්ගේ පවුල් ගස පෙන්වීම", "කෘෂිකාර්මික කාලසටහන", "සංගීත නාට්‍ය පෙළපොත", "විහාර බිත්තිවල සූවිසි බුදුවරුන්ගෙන් නියත විවරණ ලැබීම පෙළට ඇඳීම උඩරට සම්ප්‍රදායේ අනිවාර්ය අංගයකි."),
        q("මහනුවර යුගයේ 'දෙගල්දොරුව' විහාරයේ පිහිටි ලෙන් පියස්සේ ස්වභාවික හැඩය චිත්‍ර ශිල්පියා භාවිත කළේ කෙසේද?", "ගල් පර්වතයේ ඇති නෙරීම් පවා බදාමයෙන් සමතලා කර විහාර කුටිය හා සිතුවම් එක් කිරීම", "ගල කඩා ඉවත් කර යකඩ වහලක් ගැසීම", "ගලේ ඉරි තැළුණු තැන් හිස්ව තැබීම", "පියස්ස මත තෙල් සායම් රෙදි එල්ලීම", "ගල් ලෙන හා ඉදිරි මණ්ඩපය යන දෙකම සිතුවම් පද්ධතියකින් ඒකාබද්ධ කර ඇත."),
        q("මහනුවර සම්ප්‍රදායේ 'විහාරයක පිළිමගේ ඇතුළත' බිත්ති සියල්ලම සිතුවමින් පුරවා තැබීමෙන් බැතිමතාට ලැබෙන අත්දැකීම කුමක්ද?", "බෞද්ධ විශ්වීය ආධ්‍යාත්මික බව", "ඇස් කැක්කුම හා බිය ඇති වීම", "පිටතට දිව යාමේ ආශාව", "වෙළඳසැලකට ගිය හැඟීම", "වර්ණවත් රතු පසුබිම, මල් සිවිලිම හා ජාතක කතා බැතිමතා තුළ භක්ති රසය ජනිත කරයි."),
        q("මහනුවර යුගයේ චිත්‍ර කලාව හා සීගිරි චිත්‍ර කලාව අතර 'පරිමාණ හා දෘෂ්ටිකෝණ' අතින් ඇති ප්‍රධාන වෙනස කුමක්ද?", "සීගිරිය ත්‍රිමාණ පරිමාවක් දක්වන අතර මහනුවර පැතලි ද්විමාන රීතියක් දක්වයි", "මහනුවර ත්‍රිමාණ වන අතර සීගිරිය පැතලි වේ", "දෙකම ඒකලක්ෂ්‍ය රේඛීය දෘෂ්ටිකෝණයෙන් යුක්තය", "දෙකම තෙල් සායම් කැන්වස් චිත්‍ර වේ", "මහනුවර චිත්‍ර කලාව සෙවණැලි රහිත ජන සිත්තර ශෛලියක් ලෙස පැතලි බවට හුරු වී තිබේ."),
        q("මහනුවර යුගයේ 'සිත්තරා' යනුවෙන් හැඳින්වුණු කලාකරුවා විහාර කර්මාන්තයේදී සිදු කළ අනෙකුත් කාර්යයන් මොනවාද?", "මූර්ති ඇඹීම, පිළිම නෙත් තැබීම හා ආරාම අලංකරණය කිරීම", "යුද අවි පුහුණුව ලබා දීම", "රාජ්‍ය බදු අය කිරීම", "කුඹුරු හා වැව් කැණීම පමණක්", "පැරණි උඩරට කලාකරුවා චිත්‍ර, මූර්ති, වාස්තු හා ලාක්ෂා යන සියලු කලාවන්හි නිපුණයෙකු විය."),
        q("මහනුවර යුගයේ සිතුවම්වල 'සමහර අවස්ථාවලදී චරිතවල නම්' රූපයට යටින් හෝ ඉහළින් කුඩාවට ලියා තැබුවේ ඇයි?", "සාමාන්‍ය ජනතාවට කතා පුවත හා චරිත පහසුවෙන් හඳුනා ගැනීමට", "සිංහල හෝඩිය ඉගැන්වීමට පමණක්", "ශිල්පියාගේ ගාස්තුව සටහන් කිරීමට", "චිත්‍රය අවලස්සන කිරීමට", "ජාතක කතාවේ කුමන කොටසදැයි නරඹන්නාට පැහැදිලි වීම සඳහා කෙටි හැඳින්වීම් පාඨ ලියා තිබේ."),
        q("මහනුවර යුගයේ සිතුවම්වල 'රතු පසුබිමට' උඩින් යොදන කහ හා සුදු වර්ණ මගින් ඇති වන දෘශ්‍ය බලපෑම කුමක්ද?", "රූප වඩාත් දීප්තිමත්ව ඉදිරියට ඉස්මතු වී පෙනීම", "රූප සම්පූර්ණයෙන් අඳුරේ ගිලී යාම", "චිත්‍රය කොළ පැහැයට හැරීම", "බිත්තිය ඉරිතැළී යාම", "උණුසුම් තද රතු පසුබිමේ කහ හා සුදු චරිත ඉතා පැහැදිලි වර්ණ ප්‍රතිවිරෝධතාවකින් බබළයි."),
        q("මහනුවර යුගයේ බිතුසිතුවම්වල 'මකර තොරණ' ඇඳ ඇති ආකාරය කෙබඳුද?", "මකරුන් හා ඉහළ කීර්තිමුඛ රුව", "කළුගල් ගොඩගැසූ බැම්මක් ලෙස", "චීන පිඟන් කැබලි කොටුවක් ලෙස", "වීදුරු ආරුක්කුවක් ලෙස", "දොරටු හා පිළිම පසුබිම් මත මහනුවර සම්ප්‍රදායේ වර්ණවත් මකර තොරණ් සිතුවම් කර හෝ අඹා ඇත."),
        q("මහනුවර යුගයේ සිතුවම් '19 වන සියවසේ බ්‍රිතාන්‍ය පාලන යුගය' වන විට වෙනස් වීමට පටන් ගත්තේ කුමන බලපෑමක් නිසාද?", "යුරෝපීය ත්‍රිමාණ සෙවණැලි, නව තීන්ත හා දකුණු ලංකාවේ බටහිර වස්තු මුසු වීමෙන්", "චිත්‍ර ඇඳීම සම්පූර්ණයෙන් නැවැත්වීම නිසා", "චීන අධිරාජ්‍යය ලංකාව යටත් කර ගැනීම නිසා", "ප්‍රාග් ඓතිහාසික කලාවට යළි යාම නිසා", "නව යුරෝපීය ආභාසය සමඟ ක්‍රමයෙන් සාම්ප්‍රදායික පැතලි ආරෙන් මිදී දකුණු පළාත් ආර බිහිවිය."),
        q("මහනුවර යුගයේ 'ලේවැල්ල ගංගාරාමය' සහ 'හිඳගල' පසුකාලීන සිතුවම්වල දක්නට ලැබෙන පොදු තේමාව කුමක්ද?", "සූවිසි විවරණය, සත්සතිය හා ජාතක කතා පෙළ", "යුරෝපීය රජ පවුල්වල කතා", "ප්‍රාග් ඓතිහාසික සතුන්", "කර්මාන්තශාලා යන්ත්‍ර සැලසුම්", "ගංගාරාමය, දෙගල්දොරුව හා ලංකාතිලකය යන සියලු උඩරට විහාරවල මෙම පොදු තේමා මාලාව වේ."),
        q("මහනුවර යුගයේ සිත්තරා විසින් 'ජලය' (ගංගා, මුහුදු, පොකුණු) සිතුවම් කිරීමේදී යොදා ගත් සාම්ප්‍රදායික සංකේතාත්මක ක්‍රමය කුමක්ද?", "සමාන්තර රැලි හා මසුන්-නෙළුම්", "විනිවිද පෙනෙන වීදුරු තීන්ත", "තනි කළු තීරුවක් ඇඳීම", "වතුර ලෙස කැඩපත් ඇලවීම", "රළ රේඛා රටාව හා මසුන්, කැස්බෑවන් ඇඳීමෙන් ජලය බව පහසුවෙන් සංකේතවත් කෙරේ."),
        q("මහනුවර යුගයේ සිතුවම් අධ්‍යයනය කිරීමෙන් මෙරට 'ජන සමාජය' ගැන දැනගත හැකි කරුණ කුමක්ද?", "එකල ජනතාවගේ ඇඳුම්, ආභරණ, වාද්‍ය භාණ්ඩ හා චාරිත්‍ර වාරිත්‍ර", "මිනිසුන් ජීවත් වූයේ අභ්‍යවකාශයේ බව", "එකල කිසිදු සංගීත භාණ්ඩයක් නොතිබූ බව", "සියල්ලන්ම යුරෝපීය ඇඳුම් ඇඳි බව", "ජාතක කතා තුළින්ම 18 වන සියවසේ සිංහල ජන ජීවිතයේ සැබෑ ස්වරූපය චිත්‍රණය වී ඇත."),
        q("මහනුවර යුගයේ බිතුසිතුවම්වල ඇඳ ඇති 'දේවතා රූප' හා 'සාමාන්‍ය මිනිසුන්' වෙන් කර හඳුනාගන්නේ කෙසේද?", "දෙවිවරුන්ට ඔටුණු, ප්‍රභා මණ්ඩල හා උත්තරීතර ආභරණ පැවතීමෙන්", "දෙවිවරුන් කොළ පැහැයෙන් පමණක් ඇඳීමෙන්", "සාමාන්‍ය මිනිසුන්ට හිස් නොතිබීමෙන්", "දෙවිවරුන් සතුන්ගේ හැඩයෙන් සිටීමෙන්", "මකුට ඔටුණු හා අලංකාර වස්ත්‍රාභරණ මගින් දිව්‍ය හා රාජකීය චරිත පැහැදිලිව වෙන් කරයි."),
        q("මහනුවර යුගයේ චිත්‍ර කලාවේ 'මාර පරාජය' සිතුවමේ බුදුරජාණන් වහන්සේ වැඩ සිටින ආසනය හා මුද්‍රාව කුමක්ද?", "වජ්‍රාසනය මත භූමිස්පර්ශ මුද්‍රාවෙන්", "සැතපෙන ඉරියව්වෙන්", "හිටි ඉරියව්වෙන් අසිස මුද්‍රාවෙන්", "පුටුවක හිඳ ධර්මචක්‍ර මුද්‍රාවෙන්", "මහ පොළොව සාක්ෂි කර ගන්නා භූමිස්පර්ශ මුද්‍රාව දෙගල්දොරුව හා දඹුල්ල මාර පරාජයේදී දැක්වේ."),
        q("මහනුවර සම්ප්‍රදායේ 'විහාර චිත්‍ර' වර්තමානයේ අගය කිරීමේදී ඒවා 'සාම්ප්‍රදායික කතා පොතක්' මෙන් කියැවෙන්නේ ඇයි?", "පියවරෙන් පියවර සිදුවීම් පෙළ තීරු ක්‍රමයට දෘශ්‍යව ඉදිරිපත් කර ඇති බැවින්", "බිත්ති මත පොත් පිටු අලවා ඇති බැවින්", "කිසිදු රූපයක් නොමැතිව අකුරු පමණක් ඇති බැවින්", "කුඩා පින්තූර පොතක් ලෙස ගලවා ගත හැකි බැවින්", "අකුරු නොදත් බැතිමතාට පවා කතාව මුල සිට අගට තේරුම් ගැනීමට තීරු ක්‍රමය උපකාරී වේ."),
        q("මහනුවර යුගයේ චිත්‍ර කලාවේදී 'වර්ණක දිය කිරීමට' භාවිත කළ දිවුල් ලාටු මාධ්‍යය හේතුවෙන් සිතුවම්වලට ලැබුණු ගුණය කුමක්ද?", "වර්ණ බදාමයට තදින් බැඳී පැවතීම", "වර්ණ ජලයේ සේදී යාම", "වර්ණ දුඹුරු පැහැ ගැන්වීම", "බදාමය කඩා වැටීම", "ස්වභාවික දිවුල් ලාටු මැලියම් ගුණයෙන් යුතු බැවින් වර්ණක ස්ථිරව බිත්තියේ රඳා පවතී."),
        q("දෙගල්දොරුව රජමහා විහාරයේ 'වෙස්සන්තර ජාතක' සිතුවමේ සුවිශේෂී කලාත්මක අගය කුමක්ද?", "සියුම් පින්සල් පහරවල්, සංවේදී අවස්ථා නිරූපණය හා සමතුලිත සංයුතිය", "කළු-සුදු රේඛා කිහිපයක් පමණක් වීම", "බටහිර යුද නැව් ඇඳ තිබීම", "වීදුරු කැබලි ඔබ්බවා තිබීම", "ජූජක බමුණා, මන්ද්‍රි දේවිය හා ඇතු දන් දීම යන අවස්ථා උඩරට කලාවේ විශිෂ්ටතම නිදසුන් වේ."),
        q("මහනුවර යුගයේ සිතුවම්වල 'සමමිතික නෙළුම් මල් පදක්කම්' බොහෝ විට දැකිය හැක්කේ විහාරයේ කුමන කොටසේද?", "වහලයේ වියන් හා දොර උළුවහු මත", "පොළොවේ වැලි මළුව මත", "බුදු රුවේ මුහුණ මත", "පිළිම පාදමේ දර කෝටු මත", "ලෙන් වහලයේ හා ටැම්පිට විහාරවල ලී සිවිලිමේ අලංකාර නෙළුම් පදක්කම් සිතුවම් කර ඇත."),
        q("මහනුවර යුගයේ 'විහාර චිත්‍ර ශිල්පය' කලක් යටත්විජිත සමයේදී පහත වැටීමට හේතුව කුමක්ද?", "රාජකීය අනුග්‍රහය හා බටහිර ආභාසය", "මකුළු මැටි පොළොවෙන් අවසන් වීම", "විහාර සියල්ල කඩා වැටීම", "ශිල්පීන් රට හැර යාම", "1815න් පසු රාජ්‍ය අනුග්‍රහය නැති වී යාමත් සමඟ සම්ප්‍රදායික උඩරට කලා ශෛලිය ක්‍රමයෙන් වෙනස් විය."),
        q("මහනුවර යුගයේ සිතුවම් කලාව අධ්‍යයනය කරන සිසුවෙකුට එහි 'සුවිශේෂී අනන්‍යතාව' කුමන වචනවලින් හැඳින්විය හැකිද?", "රතු පසුබිම, කළු බාහිර රේඛාව, පැතලි රූප හා තීරු ක්‍රමයේ ආඛ්‍යානය", "ත්‍රිමාණ සෙවණැලි, නිල් අහස හා තෙල් සායම්", "වියුක්ත තිත්, කොටු හා වීදුරු කැට", "කළු අඟුරු සත්ව දඩයම් සිලුවට්", "මෙම ලක්ෂණ සතර මහනුවර චිත්‍ර ශෛලිය අනෙක් සියලු යුගවලින් පැහැදිලිව වෙන් කර හඳුන්වයි."),
        q("මහනුවර යුගයේ චිත්‍ර කලාව පිළිබඳ 'ආනන්ද කුමාරස්වාමි' මහතා රචනා කළ සුප්‍රකට ග්‍රන්ථය කුමක්ද?", "මධ්‍යකාලීන සිංහල කලා (Mediaeval Sinhalese Art)", "ලෝක ගුහා චිත්‍ර ඉතිහාසය", "පුනරුද යුගයේ ශිල්පීහු", "නූතන වියුක්ත චිත්‍ර", "1908 දී ප්‍රකාශිත මධ්‍යකාලීන සිංහල කලා ග්‍රන්ථය උඩරට සිතුවම්, කැටයම් හා ශිල්ප ගැන අගනා මූලාශ්‍රයකි."),
        q("මහනුවර යුගයේ 'විහාර බිතුසිතුවම්' වල පරිසරයට ගැළපෙන සේ පාට කළ 'මහ පොළොව' හා 'අහස' පෙන්වා ඇත්තේ කෙසේද?", "තනි රතු හෝ සුදු තීරු මත මල් රටා හා වලාකුළු සංකේත යෙදීමෙන්", "සැබෑ නිල් අහස හා කොළ තණකොළ ඡායාරූප ලෙස ඇඳීමෙන්", "සම්පූර්ණයෙන් කළු කර තැබීමෙන්", "භූ ගෝලීය සිතියම් ඇඳීමෙන්", "පසුබිම ස්වභාවික අහසක් ලෙස නොව අලංකාර සැරසිලි තලයක් ලෙස සලකා වලාකුළු හා මල් යොදයි.")
    )
}
